-- EXTRA TIME — Seed struttura Regionale giovanile riformulata 2026/2027
-- Fonte: CU17 SGS del 15/09/2026 (calendario Regionale completo U14-U17).
-- Sostituisce la struttura pre-riforma. Idempotente (DELETE+INSERT ON CONFLICT).

begin;

-- Pulizia struttura Regionale giovanile precedente (brochure pre-riforma):
-- rimuove partite e iscrizioni dei gironi U14-U17 Regionale della stagione
-- corrente, prima di reinserire la struttura riformulata (CU17 SGS 15/09/2026).
delete from matches where group_id in (
  select g.id from competition_groups g
    join competitions co on co.id = g.competition_id
    join seasons s on s.id = g.season_id and s.is_current
   where co.category in ('U14 Regionale','U15 Regionale','U16 Regionale','U17 Regionale'));
delete from group_teams where group_id in (
  select g.id from competition_groups g
    join competitions co on co.id = g.competition_id
    join seasons s on s.id = g.season_id and s.is_current
   where co.category in ('U14 Regionale','U15 Regionale','U16 Regionale','U17 Regionale'));

-- La stagione reale diventa quella corrente; le altre non lo sono più.
update seasons set is_current = false where is_current = true;

on conflict (id) do update set is_current = excluded.is_current;

-- Competizioni (una per categoria+livello)
on conflict (id) do nothing;

-- Gironi
on conflict (id) do nothing;

-- Club (148 società distinte)
on conflict (id) do nothing;

-- Squadre (club × categoria+livello)
on conflict (id) do nothing;

-- Iscrizioni squadra→girone
on conflict do nothing;

-- Calendario (partite programmate)
on conflict (id) do nothing;

commit;
